
document.querySelectorAll('.mobile-menu a').forEach(link=>link.addEventListener('click',()=>{link.closest('details').open=false}));
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.mobile-menu[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary').focus()})});
const carousel=document.getElementById('testimonials');
if(carousel){
const slides=[...carousel.querySelectorAll('[data-quote]')],dots=[...carousel.querySelectorAll('[data-dot-index]')],reducedMotion=matchMedia('(prefers-reduced-motion: reduce)'),heldTouches=new Set();let index=0,hovered=false,focused=false,timer;
function schedule(){clearTimeout(timer);if(!reducedMotion.matches&&!hovered&&!focused&&!heldTouches.size&&!document.hidden&&!carousel.querySelector('.full-testimonial[open]'))timer=setTimeout(()=>show(index+1,false),9000)}
function show(next,manual=true){index=(next+slides.length)%slides.length;slides.forEach((slide,i)=>{slide.classList.toggle('is-current',i===index);if(i!==index)slide.querySelector('details').open=false});dots.forEach(dot=>{if(Number(dot.dataset.dotIndex)===index)dot.setAttribute('aria-current','true');else dot.removeAttribute('aria-current')});if(manual)carousel.querySelector('.carousel-status').textContent=slides[index].querySelector('figcaption').textContent;schedule()}
carousel.querySelectorAll('[data-slide-link]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const wasArrow=link.getAttribute('aria-label')==='Next testimonial'||link.getAttribute('aria-label')==='Previous testimonial';const label=link.getAttribute('aria-label');show(Number(link.dataset.slideLink));if(wasArrow)slides[index].querySelector('a[aria-label="'+label+'"]').focus();else slides[index].querySelector('[data-dot-index="'+index+'"]').focus()}));
carousel.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'){hovered=true;schedule()}});carousel.addEventListener('pointerleave',event=>{if(event.pointerType==='mouse'){hovered=false;schedule()}});
carousel.addEventListener('touchstart',event=>{for(const touch of Array.from(event.changedTouches))heldTouches.add(touch.identifier);schedule()},{passive:true});function release(event){for(const touch of Array.from(event.changedTouches))heldTouches.delete(touch.identifier);schedule()}window.addEventListener('touchend',release,{passive:true});window.addEventListener('touchcancel',release,{passive:true});
carousel.addEventListener('focusin',()=>{focused=true;schedule()});carousel.addEventListener('focusout',event=>{focused=!!event.relatedTarget&&carousel.contains(event.relatedTarget);schedule()});carousel.querySelectorAll('.full-testimonial').forEach(details=>details.addEventListener('toggle',schedule));document.addEventListener('visibilitychange',()=>{if(document.hidden){heldTouches.clear();hovered=false}schedule()});reducedMotion.addEventListener('change',schedule);
show(0,false);carousel.classList.add('is-enhanced');
}

