const galleryDialog=document.querySelector('.image-gallery');
let galleryTrigger=null;
function openImageGallery(id,trigger){
 const item=imageGalleries[id];if(!item||!galleryDialog?.showModal)return false;
 galleryTrigger=trigger;
 galleryDialog.querySelector('#image-gallery-title').textContent=item.title;
 const photos=galleryDialog.querySelector('.gallery-photos');photos.replaceChildren();photos.classList.toggle('is-pair',item.photos.length>1);
 item.photos.forEach(photo=>{const figure=document.createElement('figure'),image=document.createElement('img');image.src=photo.src;image.alt=photo.alt;image.decoding='async';figure.append(image);if(photo.label){const caption=document.createElement('figcaption');caption.textContent=photo.label;figure.append(caption)}photos.append(figure)});
 galleryDialog.showModal();galleryDialog.scrollTop=0;document.body.style.overflow='hidden';return true;
}
document.querySelectorAll('[data-gallery]').forEach(link=>link.addEventListener('click',event=>{if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;if(openImageGallery(link.dataset.gallery,link))event.preventDefault()}));
galleryDialog?.querySelector('[data-close-gallery]').addEventListener('click',()=>galleryDialog.close());
galleryDialog?.addEventListener('click',event=>{if(event.target===galleryDialog){const r=galleryDialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)galleryDialog.close()}});
galleryDialog?.addEventListener('close',()=>{document.body.style.overflow='';galleryTrigger?.focus({preventScroll:true})});
function enquiryPayload(fields){
 const phone=fields.phone.trim(),city=fields.city.trim();
 return {name:fields.name.trim(),email:fields.email.trim(),phone,city,projectType:fields.interest==='Interiors & Furniture'?'Both':fields.interest,message:'Phone: '+phone+'\nCity: '+city+'\n\n'+fields.message.trim()};
}
const enquiryForm=document.querySelector('.contact-form');
if(enquiryForm){
 const previewMode=location.protocol==='file:'||['localhost','127.0.0.1','::1'].includes(location.hostname),button=enquiryForm.querySelector('[type="submit"]'),status=enquiryForm.querySelector('[data-form-status]');
 const buttonLabel=()=>{button.firstChild.textContent=previewMode?'Preview enquiry ':'Send enquiry '};buttonLabel();
 if(previewMode)enquiryForm.querySelector('[data-enquiry-note]').textContent='This local preview does not send or save enquiries. You can contact the studio through Instagram.';
 const query=new URLSearchParams(location.search),interest=query.get('interest');
 if(['Interiors','Furniture','Interiors & Furniture'].includes(interest))enquiryForm.elements.interest.value=interest;
 if(query.get('piece'))enquiryForm.elements.message.value='I would like to enquire about '+query.get('piece')+'.';
 enquiryForm.addEventListener('submit',async event=>{
  event.preventDefault();if(!enquiryForm.reportValidity())return;
  if(previewMode){status.textContent='Preview complete. Your enquiry has not been sent or saved.';return}
  button.disabled=true;button.firstChild.textContent='Sending… ';status.textContent='';
  try{const fields=Object.fromEntries(new FormData(enquiryForm)),payload=enquiryPayload(fields),response=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Unable to send your enquiry.');status.textContent='Thank you. Your enquiry has been received.';enquiryForm.reset()}
  catch(error){status.textContent=(error.message==='Failed to fetch'?'We could not send your enquiry.':error.message)+' Please try again or message us on Instagram.'}
  finally{button.disabled=false;buttonLabel()}
 });
}

document.querySelectorAll('.transformation-toggle').forEach(button=>button.addEventListener('click',()=>{const showBefore=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(showBefore));const name=button.closest('article').querySelector('h3').textContent;button.setAttribute('aria-label','Show '+(showBefore?'after':'before')+' photo of '+name.toLowerCase());button.querySelector('.hint-touch').textContent=showBefore?'Tap to see after':'Tap to see before'}));

// Fetch invisible alternate views only when a visitor approaches the interaction.
document.querySelectorAll('.paired-collection summary').forEach(summary=>{const load=()=>{const img=summary.querySelector('img[data-src]');if(!img)return;img.onload=()=>{img.dataset.loaded='true'};img.srcset=img.dataset.srcset||'';img.src=img.dataset.src;delete img.dataset.src;delete img.dataset.srcset};summary.addEventListener('pointerenter',load,{once:true});summary.addEventListener('focus',load,{once:true});summary.addEventListener('pointerdown',load,{once:true})});
